 * BLASWrapper.cpp - High-Performance C++ Wrapper for BLAS (Basic Linear Algebra Subprograms)
 * Providing a modern interface to legacy Fortran BLAS kernels.
 */

#include <iostream>
#include <vector>
#include <iomanip>

extern "C" {
    // BLAS Level 1: Vector Scaling x = alpha * x
    void dscal_(const int* n, const double* alpha, double* x, const int* incx);

    // BLAS Level 1: Vector-Vector Addition y = alpha * x + y
    void daxpy_(const int* n, const double* alpha, const double* x, const int* incx, double* y, const int* incy);

    // BLAS Level 1: Dot Product res = x^T * y
    double ddot_(const int* n, const double* x, const int* incx, const double* y, const int* incy);

    // BLAS Level 3: Matrix-Matrix Multiplication C = alpha * A * B + beta * C
    void dgemm_(const char* transa, const char* transb, const int* m, const int* n, const int* k,
                const double* alpha, const double* a, const int* lda,
                const double* b, const int* ldb,
                const double* beta, double* c, const int* ldc);
}

class BLASWrapper {
public:
    static void VectorScale(std::vector<double>& x, double alpha) {
        int n = static_cast<int>(x.size());
        int incx = 1;
        dscal_(&n, &alpha, x.data(), &incx);
    }

    static void VectorAdd(const std::vector<double>& x, std::vector<double>& y, double alpha = 1.0) {
        int n = static_cast<int>(x.size());
        int incx = 1;
        int incy = 1;
        daxpy_(&n, &alpha, x.data(), &incx, y.data(), &incy);
    }

    static double DotProduct(const std::vector<double>& x, const std::vector<double>& y) {
        int n = static_cast<int>(x.size());
        int incx = 1;
        int incy = 1;
        return ddot_(&n, x.data(), &incx, y.data(), &incy);
    }

    static void MatrixMultiply(int m, int n, int k, double alpha, const std::vector<double>& A, 
                               const std::vector<double>& B, double beta, std::vector<double>& C) {
        char transa = 'N';
        char transb = 'N';
        int lda = m;
        int ldb = k;
        int ldc = m;
        dgemm_(&transa, &transb, &m, &n, &k, &alpha, A.data(), &lda, B.data(), &ldb, &beta, C.data(), &ldc);
    }
};

int main() {
    std::cout << "🚀 C++ BLAS WRAPPER INTERFACE" << std::endl;
    std::cout << "=============================" << std::endl;

    // Vector operations demo
    std::vector<double> x = {1.0, 2.0, 3.0};
    std::vector<double> y = {4.0, 5.0, 6.0};

    std::cout << "1. Vector Operations:" << std::endl;
    double dot = BLASWrapper::DotProduct(x, y);
    std::cout << "   x . y = " << dot << " (Expected: 32.0)" << std::endl;

    BLASWrapper::VectorAdd(x, y, 2.0); // y = 2*x + y
    std::cout << "   y = 2x + y: [" << y[0] << ", " << y[1] << ", " << y[2] << "]" << std::endl;

    // Matrix multiplication demo
    std::cout << "\n2. Matrix Operations (GEMM):" << std::endl;
    int m = 2, n = 2, k = 2;
    std::vector<double> A = {1.0, 2.0, 3.0, 4.0}; // 2x2
    std::vector<double> B = {5.0, 6.0, 7.0, 8.0}; // 2x2
    std::vector<double> C(4, 0.0);

    BLASWrapper::MatrixMultiply(m, n, k, 1.0, A, B, 0.0, C);
    std::cout << "   C = A * B:" << std::endl;
    std::cout << "   [" << C[0] << " " << C[2] << "]" << std::endl;
    std::cout << "   [" << C[1] << " " << C[3] << "]" << std::endl;

