}

// ParticleSim.cpp - High-performance particle physics simulation
#include <iostream>
#include <vector>
#include <cmath>
#include <random>

struct Particle {
    double x, y, z;     // Position
    double vx, vy, vz;  // Velocity
    double ax, ay, az;  // Acceleration
    double mass;

    void update(double dt) {
        // Velocity Verlet integration
        x += vx * dt + 0.5 * ax * dt * dt;
        y += vy * dt + 0.5 * ay * dt * dt;
        z += vz * dt + 0.5 * az * dt * dt;

        vx += ax * dt;
        vy += ay * dt;
        vz += az * dt;

        // Reset acceleration
        ax = ay = az = 0.0;
    }
};

class ParticleSystem {
    std::vector<Particle> particles;

public:
    ParticleSystem(int n) {
        std::mt19937 gen(42);
        std::uniform_real_distribution<> dis(-1.0, 1.0);

        particles.resize(n);
        for (auto& p : particles) {
            p.x = dis(gen);
            p.y = dis(gen);
            p.z = dis(gen);
            p.vx = dis(gen) * 0.1;
            p.vy = dis(gen) * 0.1;
            p.vz = dis(gen) * 0.1;
            p.mass = 1.0;
        }
    }

    void compute_forces() {
        const double G = 0.01;  // Gravitational constant
        const double softening = 0.1;

        #pragma omp parallel for
        for (size_t i = 0; i < particles.size(); ++i) {
            for (size_t j = i + 1; j < particles.size(); ++j) {
                double dx = particles[j].x - particles[i].x;
                double dy = particles[j].y - particles[i].y;
                double dz = particles[j].z - particles[i].z;

                double r2 = dx*dx + dy*dy + dz*dz + softening*softening;
                double r = std::sqrt(r2);
                double f = G / (r2 * r);

                particles[i].ax += f * dx * particles[j].mass;
                particles[i].ay += f * dy * particles[j].mass;
                particles[i].az += f * dz * particles[j].mass;

                particles[j].ax -= f * dx * particles[i].mass;
                particles[j].ay -= f * dy * particles[i].mass;
                particles[j].az -= f * dz * particles[i].mass;
            }
        }
    }

    void step(double dt) {
        compute_forces();
        #pragma omp parallel for
        for (auto& p : particles) {
            p.update(dt);
        }
    }

    double kinetic_energy() const {
        double ke = 0.0;
        for (const auto& p : particles) {
            ke += 0.5 * p.mass * (p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
        }
        return ke;
    }
};

int main() {
    std::cout << "⚛️ C++ Particle Simulation\\n";

    const int N = 100;
    const double dt = 0.01;
    const int steps = 1000;

    ParticleSystem system(N);

    std::cout << "   Simulating " << N << " particles...\\n";

    for (int i = 0; i < steps; ++i) {
        system.step(dt);

        if (i % 100 == 0) {
            double ke = system.kinetic_energy();
            std::cout << "   Step " << i << ": KE = " << ke << "\\n";
        }
    }

    std::cout << "✅ Simulation Complete\\n";
    return 0;
}

#include <iostream>
