using namespace Eigen;

class HPStats {
public:
    // High-performance mean using Eigen
    static double mean(const VectorXd& data) {
        return data.mean();
    }

    // Variance (unbiased)
    static double variance(const VectorXd& data) {
        double m = mean(data);
        return ((data.array() - m).square().sum()) / (data.size() - 1);
    }

    // Standard deviation
    static double stddev(const VectorXd& data) {
        return std::sqrt(variance(data));
    }

    // Covariance matrix
    static MatrixXd covariance(const MatrixXd& data) {
        // data is n x p (samples x features)
        int n = data.rows();

        // Center the data
        VectorXd means = data.colwise().mean();
        MatrixXd centered = data.rowwise() - means.transpose();

        // Cov = (X^T X) / (n - 1)
        return (centered.transpose() * centered) / (n - 1);
    }

    // Principal Component Analysis
    static std::pair<MatrixXd, VectorXd> pca(const MatrixXd& data, int n_components) {
        MatrixXd cov = covariance(data);

        // Eigendecomposition
        SelfAdjointEigenSolver<MatrixXd> eigensolver(cov);

        // Sort eigenvalues/vectors in descending order
        VectorXd eigenvalues = eigensolver.eigenvalues().reverse();
        MatrixXd eigenvectors = eigensolver.eigenvectors().rowwise().reverse();

        // Select top components
        MatrixXd components = eigenvectors.leftCols(n_components);
        VectorXd explained_var = eigenvalues.head(n_components);

        return {components, explained_var};
    }

    // Pearson correlation
    static double correlation(const VectorXd& x, const VectorXd& y) {
        double mx = mean(x);
        double my = mean(y);

        double num = ((x.array() - mx) * (y.array() - my)).sum();
        double den = std::sqrt(
            ((x.array() - mx).square().sum()) *
            ((y.array() - my).square().sum())
        );

        return num / den;
    }
};

int main() {
    std::cout << "⚡ C++ High-Performance Stats (Eigen)\\n";

    // Generate test data
    MatrixXd data(100, 3);
    data.setRandom();

    std::cout << "\\n1. Basic Statistics:\\n";
    VectorXd col0 = data.col(0);
    std::cout << "   Mean: " << HPStats::mean(col0) << "\\n";
    std::cout << "   Std Dev: " << HPStats::stddev(col0) << "\\n";

    std::cout << "\\n2. Covariance Matrix:\\n";
    MatrixXd cov = HPStats::covariance(data);
    std::cout << cov << "\\n";

    std::cout << "\\n3. PCA (top 2 components):\\n";
    auto [components, explained_var] = HPStats::pca(data, 2);
    std::cout << "   Explained variance: " << explained_var.transpose() << "\\n";

    std::cout << "\\n4. Correlation:\\n";
    double corr = HPStats::correlation(data.col(0), data.col(1));
    std::cout << "   r(col0, col1) = " << corr << "\\n";

    std::cout << "\\n✅ HP Stats Complete\\n";
    return 0;
}

