import numpy as np
from scipy.stats import entropy

class InformationEngine:
    @staticmethod
    def shannon_entropy(probabilities):
        """Calcula la entropía de Shannon: H(X) = -Σ p(x) log p(x)"""
        return entropy(probabilities, base=2)

    @staticmethod
    def mutual_information(p_xy, p_x, p_y):
        """MI(X;Y) = Σ p(x,y) log(p(x,y) / (p(x)p(y)))"""
        mi = 0
        for i in range(len(p_x)):
            for j in range(len(p_y)):
                if p_xy[i][j] > 0:
                    mi += p_xy[i][j] * np.log2(p_xy[i][j] / (p_x[i] * p_y[j]))
        return mi

    @staticmethod
    def kl_divergence(p, q):
        """Divergencia de Kullback-Leibler (Distancia relativa)"""
        return np.sum(np.where(p != 0, p * np.log2(p / q), 0))

def run_test():
    print("📊 JARVIX INFO-ENGINE: Entropy & Mutual Information")
    engine = InformationEngine()

    # Dataset: Sistema binario con ruido
    p = [0.8, 0.2]
    h = engine.shannon_entropy(p)
    print(f"   Shannon Entropy (H): {h:.4f} bits")

    # KL Divergence entre distribución real y uniforme
