# AlgebraicTopology.py - Pure Mathematics: Algebraic Topology
# Complete implementation of fundamental group, homology, and cohomology basics

import numpy as np
from typing import List, Set, Tuple, Optional
from dataclasses import dataclass
from collections import defaultdict

# =============================================================================
# SIMPLICIAL COMPLEXES
# =============================================================================

@dataclass(frozen=True)
class Simplex:
    """n-simplex defined by vertices."""
    vertices: Tuple[int, ...]

    def __post_init__(self):
        # Ensure vertices are sorted
        object.__setattr__(self, 'vertices', tuple(sorted(self.vertices)))

    @property
    def dimension(self) -> int:
        """Dimension of simplex (n for n-simplex)."""
        return len(self.vertices) - 1

    def faces(self) -> List['Simplex']:
        """Return all (n-1)-faces."""
        if self.dimension == 0:
            return []

        faces = []
        for i in range(len(self.vertices)):
            face_vertices = self.vertices[:i] + self.vertices[i+1:]
            faces.append(Simplex(face_vertices))
        return faces

    def __repr__(self):
        return f"σ{self.dimension}{self.vertices}"

class SimplicialComplex:
    """Simplicial complex K."""

    def __init__(self):
        self.simplices: Set[Simplex] = set()

    def add_simplex(self, simplex: Simplex):
        """Add simplex and all its faces."""
        self.simplices.add(simplex)

        # Add all faces recursively
        for face in simplex.faces():
            self.add_simplex(face)

    def get_simplices(self, dimension: int) -> List[Simplex]:
        """Get all n-simplices."""
        return [s for s in self.simplices if s.dimension == dimension]

    def euler_characteristic(self) -> int:
        """Compute Euler characteristic χ = Σ (-1)^n * #n-simplices."""
        max_dim = max(s.dimension for s in self.simplices) if self.simplices else 0

        chi = 0
        for n in range(max_dim + 1):
            count = len(self.get_simplices(n))
            chi += ((-1) ** n) * count

        return chi

    def __repr__(self):
        counts = defaultdict(int)
        for s in self.simplices:
            counts[s.dimension] += 1

        dims_str = ", ".join(f"{d}-simplices: {count}" 
                            for d, count in sorted(counts.items()))
        return f"SimplicialComplex({dims_str})"

# =============================================================================
# CHAIN COMPLEXES AND HOMOLOGY
# =============================================================================

class ChainComplex:
    """Chain complex with boundary operators."""

    def __init__(self, complex: SimplicialComplex):
        self.complex = complex
        self.max_dim = max((s.dimension for s in complex.simplices), default=0)

        # Build boundary matrices
        self.boundary_matrices = {}
        for n in range(self.max_dim + 1):
            self.boundary_matrices[n] = self._compute_boundary_matrix(n)

    def _compute_boundary_matrix(self, n: int) -> np.ndarray:
        """Compute nth boundary operator ∂_n : C_n → C_{n-1}."""
        if n == 0:
            return np.array([[]])

        n_simplices = sorted(self.complex.get_simplices(n), key=lambda s: s.vertices)
        n_minus_1_simplices = sorted(self.complex.get_simplices(n-1), 
                                     key=lambda s: s.vertices)

        if not n_simplices or not n_minus_1_simplices:
            return np.array([[]])

        # Create boundary matrix
        rows = len(n_minus_1_simplices)
        cols = len(n_simplices)
        matrix = np.zeros((rows, cols), dtype=int)

        for j, simplex in enumerate(n_simplices):
            for i, face_with_sign in enumerate(simplex.faces()):
                sign = (-1) ** i
                face_idx = n_minus_1_simplices.index(face_with_sign)
                matrix[face_idx, j] = sign

