# =============================================================================
# PRIME NUMBERS
# =============================================================================

def sieve_of_eratosthenes(n: int) -> List[int]:
    """Sieve of Eratosthenes for primes up to n."""
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(np.sqrt(n)) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False

    return [i for i, prime in enumerate(is_prime) if prime]

def prime_counting_function(x: float) -> int:
    """π(x) - number of primes ≤ x."""
    if x < 2:
        return 0
    primes = sieve_of_eratosthenes(int(x))
    return len(primes)

def prime_number_theorem_estimate(x: float) -> float:
    """PNT estimate: π(x) ~ x / ln(x)."""
    if x < 2:
        return 0
    return x / np.log(x)

def li_function(x: float) -> float:
    """Logarithmic integral li(x) - better estimate for π(x)."""
    if x <= 1:
        return 0

    # li(x) ≈ x/ln(x) * (1 + 1/ln(x) + 2!/ln²(x) + ...)
    # Using asymptotic expansion
    log_x = np.log(x)

    result = x / log_x
    term = result

    for k in range(1, 10):
        term = term * k / log_x
        result += term

    return result

# =============================================================================
