# =============================================================================

def extended_gcd(a: int, b: int) -> Tuple[int, int, int]:
    """Extended Euclidean algorithm: returns (gcd, x, y) where ax + by = gcd."""
    if b == 0:
        return (a, 1, 0)

    gcd, x1, y1 = extended_gcd(b, a % b)
    x = y1
    y = x1 - (a // b) * y1

    return (gcd, x, y)

def mod_inverse(a: int, m: int) -> Optional[int]:
    """Modular multiplicative inverse: a⁻¹ (mod m)."""
    gcd, x, _ = extended_gcd(a, m)

    if gcd != 1:
        return None  # Inverse doesn't exist

    return x % m

def chinese_remainder_theorem(remainders: List[int], moduli: List[int]) -> Optional[int]:
    """Chinese Remainder Theorem solver."""
    if len(remainders) != len(moduli):
        raise ValueError("Lists must have same length")

    # Check pairwise coprimality
    for i in range(len(moduli)):
        for j in range(i + 1, len(moduli)):
            if math.gcd(moduli[i], moduli[j]) != 1:
                return None  # Not pairwise coprime

    # Compute solution
    M = math.prod(moduli)
    result = 0

    for r, m in zip(remainders, moduli):
        M_i = M // m
        inv = mod_inverse(M_i, m)
        if inv is None:
            return None
        result += r * M_i * inv

    return result % M

def euler_phi(n: int) -> int:
    """Euler's totient function φ(n) - count of integers ≤ n coprime to n."""
    if n == 1:
        return 1

    result = n
    p = 2

    # Factor n and apply formula: φ(n) = n * ∏(1 - 1/p)
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1

    if n > 1:
        result -= result // n

    return result

def primitive_root(p: int) -> Optional[int]:
    """Find a primitive root modulo prime p."""
    if p == 2:
        return 1

    # φ(p) = p - 1 for prime p
    phi = p - 1

    # Factor phi
    factors = set()
    temp = phi
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)

    # Check each candidate
