/*
📊 SPC REAL-TIME MONITOR (RUST) - ELITE VERSION
===============================================
Logic:
1. Stream synthetic input data (simulated sensor).
2. Calculate Moving Average and Range.
3. Nelson Rules Detection:
   - Rule 1: One point beyond 3 sigma.
   - Rule 2: Nine points in a row on the same side of mean.
   - Rule 3: Six points in a row steadily increasing or decreasing.
*/

use std::time::{SystemTime, UNIX_EPOCH};

struct SPCEngine {
    mean: f64,
    sigma: f64,
    history: Vec<f64>,
}

impl SPCEngine {
    fn new(mean: f64, sigma: f64) -> Self {
        Self { mean, sigma, history: Vec::new() }
    }

    fn check_nelson_rules(&self, val: f64) -> Vec<String> {
        let mut alerts = Vec::new();
        let ucl = self.mean + 3.0 * self.sigma;
        let lcl = self.mean - 3.0 * self.sigma;

        // Rule 1: Beyond 3 sigma
        if val > ucl || val < lcl {
            alerts.push("RULE 1: Point beyond 3-sigma!".to_string());
        }

        // Rule 2: 9 points on same side
        if self.history.len() >= 8 {
            let last_8 = &self.history[self.history.len()-8..];
            let side = val > self.mean;
            if last_8.iter().all(|&x| (x > self.mean) == side) {
                alerts.push("RULE 2: 9 points on same side (Shift detect)".to_string());
            }
        }

        alerts
    }

    fn process(&mut self, val: f64) {
        let timestamp = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis();
        let alerts = self.check_nelson_rules(val);

        self.history.push(val);

        let status = if alerts.is_empty() { "✅ NORMAL" } else { "🚨 ANOMALY" };
        println!("[{}] Val={:.2} -> {}", timestamp, val, status);

        for alert in alerts {
            println!("   ↳ ALERT: {}", alert);
        }
    }
}

