    println!("🤖 IA TERMINAL: RUST SPC MONITOR V2.0");
    println!("=====================================");

    let mut engine = SPCEngine::new(100.0, 1.5);
    let stream = vec![100.1, 99.5, 101.2, 102.5, 104.2, 105.1, 106.0, 105.5, 105.8, 106.2];

    for val in stream {
        engine.process(val);
    }
}

